  "knowledge": "Communication Zone Status",
  "description": "Evaluates the communication coverage and reliability in different operational zones.",
  "definition": "A zone is classified as having 'Reliable Coverage' when equipment within it maintains a CRI > 7, has active satellite connections (satellite status = 'Connected'), and supports emergency beacon functionality (emergency beacon status != 'Inactive')."
}

